type Cache struct {
	sync.Mutex
	items map[string]string
}

func (c *Cache) Set(k, v string) {
	c.Lock()
	defer c.Unlock()
	c.items[k] = v
}

func main() {
	c := &Cache{items: map[string]string{}}
	c.Lock() // code outside the type takes the lock
	c.Set("a", "1")
	fmt.Println("unreachable")
}
